import * as z from "zod/v4";
import { defineTool } from "../../../tools.js";
import extension from "../extension.js";
import { evaluate } from "../lib/evaluate.js";
const booleanQuestion = z.object({
    id: z.string().min(1),
    type: z.literal("boolean"),
    instructions: z.string().min(1),
});
const choiceQuestion = z.object({
    id: z.string().min(1),
    type: z.literal("choice"),
    instructions: z.string().min(1),
    criteria: z.record(z.string(), z.string()),
});
const scoreQuestion = z.object({
    id: z.string().min(1),
    type: z.literal("score"),
    instructions: z.string().min(1),
    criteria: z.array(z.string()).min(2),
});
const question = z.discriminatedUnion("type", [booleanQuestion, choiceQuestion, scoreQuestion]);
function toQuestionMap(questions) {
    const map = {};
    for (const item of questions) {
        if (item.type === "boolean") {
            map[item.id] = {
                type: "boolean",
                instructions: item.instructions,
            };
        }
        else if (item.type === "choice") {
            map[item.id] = {
                type: "choice",
                instructions: item.instructions,
                criteria: item.criteria,
            };
        }
        else {
            map[item.id] = {
                type: "score",
                instructions: item.instructions,
                criteria: item.criteria,
            };
        }
    }
    return map;
}
const evaluateTool = defineTool({
    description: "Ask Jev for typed boolean, choice, or score answers over one state. Returns answers only; it does not post, assign, or merge.",
    effect: "read",
    inputSchema: z
        .object({
        state: z
            .union([z.string(), z.array(z.unknown()), z.record(z.string(), z.unknown())])
            .describe("Ticket, pull request, or other state Jev should judge. Not repo source."),
        questions: z
            .array(question)
            .min(1)
            .describe("One or more typed questions over the same state."),
    })
        .refine((input) => new Set(input.questions.map((item) => item.id)).size === input.questions.length, "questions must not repeat an id"),
    async execute(input) {
        return evaluate({
            state: input.state,
            questions: toQuestionMap(input.questions),
            apiKey: extension.config.apiKey,
            model: extension.config.model,
        });
    },
});
export default evaluateTool;
